const item = $input.item.json;

// Initialize aggressive window if not started yet
if (!item.aggressive_start) {
  const now = new Date();
  const end = new Date(now);
  end.setDate(end.getDate() + 30);
  item._initAggressive = true;
  item._aggressiveStart = now.toISOString();
  item._aggressiveEnd = end.toISOString();
  item._dayNumber = 1;
} else {
  item._initAggressive = false;
  item._aggressiveStart = item.aggressive_start;
  item._aggressiveEnd = item.aggressive_end;
  item._dayNumber = (item.aggressive_days_sent || 0) + 1;
}

// Check if already sent today
if (item.lastReminderSent) {
  const lastSent = new Date(item.lastReminderSent);
  const today = new Date();
  if (lastSent.toDateString() === today.toDateString()) {
    item._skipToday = true;
  } else {
    item._skipToday = false;
  }
} else {
  item._skipToday = false;
}

// Generate new token if expired
if (!item.confirmation_token || !item.token_expires_at || new Date(item.token_expires_at) < new Date()) {
  item._needsNewToken = true;
  item._newToken = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
} else {
  item._needsNewToken = false;
  item._newToken = item.confirmation_token;
}

return item;

