parameters.jsCode:
const items = $input.all();
let hasSuccess = false;

for (const item of items) {
  if (item.json.accepted && item.json.accepted.length > 0 && 
      (!item.json.rejected || item.json.rejected.length === 0)) {
    hasSuccess = true;
    break;
  }
  if (item.json.data) {
    try {
      const smsData = JSON.parse(item.json.data);
      if (smsData.id === 'OK' && smsData.data?.recipients?.accepted?.length > 0) {
        hasSuccess = true;
        break;
      }
    } catch (e) {}
  }
}

return hasSuccess ? [{ success: true }] : [{ success: false }];

parameters.query:
UPDATE vehicle_notifications
SET aggressive_days_sent = COALESCE(aggressive_days_sent, 0) + 1,
    "lastReminderSent" = NOW()
WHERE id = {{ $node['Initialize & Update Token'].json.id }}
RETURNING *;

